begin;
set local lock_timeout = '500ms';
set local statement_timeout = '8s';
set local application_name = 'cyclostratege-secondary-sponsor-brand-names-20261106';

-- Only remove the country suffix generated by the original ten templates.
-- Country associations and catalog keys remain the identity of each entry.
with templates(slot_number, brand_name) as (values
  (1,'Novara'),(2,'Altis'),(3,'Meridian'),(4,'Vektor'),(5,'Luma'),
  (6,'Orbis'),(7,'Summit'),(8,'Ardent'),(9,'TerraNova'),(10,'Pulse')
)
update public.secondary_sponsor_catalog sponsor
set name = template.brand_name
from public.countries country, templates template
where sponsor.country_id = country.id and sponsor.slot_number = template.slot_number
  and sponsor.catalog_key = 'secondary-' || lower(country.iso_alpha2) || '-' || template.slot_number
  and sponsor.name = template.brand_name || ' ' || country.iso_alpha2;

-- Activation copied the old sponsor label into the current team's identity.
-- Repair only its recognizable trailing component, including a one-letter
-- country suffix clipped by the existing 30-character short-name limit.
-- Never rewrite archived seasons, sporting results or unrelated custom names.
with templates(slot_number, brand_name) as (values
  (1,'Novara'),(2,'Altis'),(3,'Meridian'),(4,'Vektor'),(5,'Luma'),
  (6,'Orbis'),(7,'Summit'),(8,'Ardent'),(9,'TerraNova'),(10,'Pulse')
), identities as (
  select team.id, team.display_name, team.short_name, template.brand_name,
    template.brand_name || ' ' || country.iso_alpha2 as old_name, country.iso_alpha2
  from public.secondary_sponsor_contracts contract
  join public.secondary_sponsor_catalog sponsor on sponsor.id = contract.secondary_sponsor_id
  join public.countries country on country.id = sponsor.country_id
  join templates template on template.slot_number = sponsor.slot_number and template.brand_name = sponsor.name
  join public.team_seasons team on team.team_id = contract.team_id and team.season_id = contract.season_id
  join public.seasons season on season.id = team.season_id
  where contract.status in ('active','planned') and team.status in ('active','planned')
    and season.status in ('active','planned')
    and sponsor.catalog_key = 'secondary-' || lower(country.iso_alpha2) || '-' || template.slot_number
), repaired as (
  select id,
    case when right(display_name, length(' - ' || old_name)) = ' - ' || old_name
      then left(display_name, length(display_name) - length(old_name)) || brand_name
      else display_name end as display_name,
    case when right(short_name, length('-' || old_name)) = '-' || old_name
      then left(short_name, length(short_name) - length(old_name)) || brand_name
      when length(short_name) = 30
        and right(short_name, length('-' || brand_name || ' ' || left(iso_alpha2,1)))
          = '-' || brand_name || ' ' || left(iso_alpha2,1)
      then left(short_name, length(short_name) - 2)
      else short_name end as short_name
  from identities
)
update public.team_seasons team
set display_name = repaired.display_name, short_name = repaired.short_name
from repaired where team.id = repaired.id
  and (team.display_name, team.short_name) is distinct from (repaired.display_name, repaired.short_name);

-- Backstop a future import/reseed using the old generated label. The exact
-- country/key/template match preserves real brand acronyms and custom names.
create function private.normalize_secondary_sponsor_brand_name()
returns trigger language plpgsql security definer set search_path = ''
as $$
declare v_country_code text; v_brand text;
begin
  v_brand := (array['Novara','Altis','Meridian','Vektor','Luma',
    'Orbis','Summit','Ardent','TerraNova','Pulse'])[new.slot_number];
  if v_brand is null then return new; end if;
  select iso_alpha2 into v_country_code from public.countries where id = new.country_id;
  if new.catalog_key = 'secondary-' || lower(v_country_code) || '-' || new.slot_number
    and new.name = v_brand || ' ' || v_country_code then
    new.name := v_brand;
  end if;
  return new;
end;
$$;
create trigger normalize_secondary_sponsor_brand_name_before_write
before insert or update of name, country_id, slot_number, catalog_key
on public.secondary_sponsor_catalog for each row
execute function private.normalize_secondary_sponsor_brand_name();
revoke all on function private.normalize_secondary_sponsor_brand_name()
  from public, anon, authenticated, service_role;

notify pgrst, 'reload schema';
commit;
